def count_divisors(n):
    """Calculates the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

solutions = []
for k in range(1, 31):
    N = 2 * (k**3)
    d_N = count_divisors(N)
    target = 2 * k

    if d_N == target:
        solutions.append(k)
        print(f"k={k}: d({N})={d_N}, 2k={target}. Solution found.")
    else:
        print(f"k={k}: d({N})={d_N}, 2k={target}. No solution.")

print(f"\nAll solutions found: {solutions}")

def count_divisors(n):
    if n == 1:
        return 1
    divs = 1
    d = 2
    temp = n
    while d * d <= temp:
        count = 0
        while temp % d == 0:
            count += 1
            temp //= d
        divs *= (count + 1)
        d += 1
    if temp > 1:
        divs *= 2
    return divs

def solve_problem(k):
    if k <= 0:
        return False
    n = 2 * (k**3)
    tau_n = count_divisors(n)
    target = 2 * k
    return tau_n == target

candidates_a = [1, 4, 10]
results = {}
for k in candidates_a:
    results[k] = solve_problem(k)

print(f"Checking Candidate A values: {results}")

